class Leaderboard:
    def __init__(self) -> None:
        self.totals: dict[str, int] = {}  # each player's total

    def add_score(self, player: str, score: int) -> None:
        self.totals[player] = self.totals.get(player, 0) + score

    def top(self, k: int) -> str:
        # Highest total first, then names in alphabetical order.
        ranked = sorted(self.totals.items(), key=lambda item: (-item[1], item[0]))
        return " ".join(f"{name}:{total}" for name, total in ranked[:k]) or "empty"

    def reset(self, player: str) -> None:
        self.totals.pop(player, None)


