#include <algorithm>
#include <iostream>
#include <map>
#include <string>
#include <utility>
#include <vector>

class Leaderboard {
public:
    void addScore(const std::string& player, int score) {
        totals_[player] += score;
    }

    std::string top(int k) const {
        std::vector<std::pair<std::string, int>> ranked(totals_.begin(), totals_.end());
        // Highest total first, then names in alphabetical order.
        std::sort(ranked.begin(), ranked.end(), [](const auto& a, const auto& b) {
            if (a.second != b.second) {
                return a.second > b.second;
            }
            return a.first < b.first;
        });
        std::string best;
        for (int i = 0; i < k && i < static_cast<int>(ranked.size()); i++) {
            best += (i > 0 ? " " : "") + ranked[i].first + ":" + std::to_string(ranked[i].second);
        }
        return best.empty() ? "empty" : best;
    }

    void reset(const std::string& player) {
        totals_.erase(player);
    }

private:
    std::map<std::string, int> totals_; // each player's total
};

int main() {
    int q;
    std::cin >> q;
    Leaderboard board;
    for (int i = 0; i < q; i++) {
        std::string op, player;
        std::cin >> op;
        if (op == "addScore") {
