import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int q = in.nextInt();
        Leaderboard board = new Leaderboard();
        for (int i = 0; i < q; i++) {
            String op = in.next();
            if (op.equals("addScore")) {
                String player = in.next();
                board.addScore(player, in.nextInt());
            } else if (op.equals("top")) {
                System.out.println(board.top(in.nextInt()));
            } else {
                board.reset(in.next());
            }
        }
    }
}

class Leaderboard {
    private final Map<String, Integer> totals = new HashMap<>(); // each player's total

    void addScore(String player, int score) {
        totals.merge(player, score, Integer::sum);
    }

    String top(int k) {
        List<Map.Entry<String, Integer>> ranked = new ArrayList<>(totals.entrySet());
        // Highest total first, then names in alphabetical order.
        ranked.sort((a, b) -> a.getValue().equals(b.getValue())
                ? a.getKey().compareTo(b.getKey())
                : Integer.compare(b.getValue(), a.getValue()));
        List<String> best = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : ranked.subList(0, Math.min(k, ranked.size()))) {
            best.add(entry.getKey() + ":" + entry.getValue());
        }
        return best.isEmpty() ? "empty" : String.join(" ", best);
    }

    void reset(String player) {
        totals.remove(player);
    }
}

