package main

import (
	"fmt"
	"sort"
	"strings"
)

// Leaderboard ranks players by their total points.
type Leaderboard struct {
	totals map[string]int // each player's total
}

func newLeaderboard() *Leaderboard {
	return &Leaderboard{totals: map[string]int{}}
}

func (b *Leaderboard) addScore(player string, score int) {
	b.totals[player] += score
}

func (b *Leaderboard) top(k int) string {
	if len(b.totals) == 0 {
		return "empty"
	}
	players := make([]string, 0, len(b.totals))
	for player := range b.totals {
		players = append(players, player)
	}
	// Highest total first, then names in alphabetical order.
	sort.Slice(players, func(i, j int) bool {
		if b.totals[players[i]] != b.totals[players[j]] {
			return b.totals[players[i]] > b.totals[players[j]]
		}
		return players[i] < players[j]
	})
	if k < len(players) {
		players = players[:k]
	}
	best := make([]string, len(players))
	for i, player := range players {
		best[i] = fmt.Sprintf("%s:%d", player, b.totals[player])
	}
	return strings.Join(best, " ")
}

func (b *Leaderboard) reset(player string) {
	delete(b.totals, player)
}

func main() {
	var q int
	fmt.Scan(&q)
	board := newLeaderboard()
	for i := 0; i < q; i++ {
		var op, player string
		var n int
		fmt.Scan(&op)
		switch op {
		case "addScore":
			fmt.Scan(&player, &n)
			board.addScore(player, n)
		case "top":
			fmt.Scan(&n)
			fmt.Println(board.top(n))
		case "reset":
			fmt.Scan(&player)
			board.reset(player)
		}
	}
}

